// ISO 3166-1 alpha-2 country codes. Display names are generated by the runtime,
// so the selector can cover countries without maintaining translated labels by hand.
const ISO_CODES = "AD AE AF AG AI AL AM AO AQ AR AS AT AU AW AX AZ BA BB BD BE BF BG BH BI BJ BL BM BN BO BQ BR BS BT BV BW BY BZ CA CC CD CF CG CH CI CK CL CM CN CO CR CU CV CW CX CY CZ DE DJ DK DM DO DZ EC EE EG EH ER ES ET FI FJ FK FM FO FR GA GB GD GE GF GG GH GI GL GM GN GP GQ GR GS GT GU GW GY HK HM HN HR HT HU ID IE IL IM IN IO IQ IR IS IT JE JM JO JP KE KG KH KI KM KN KP KR KW KY KZ LA LB LC LI LK LR LS LT LU LV LY MA MC MD ME MF MG MH MK ML MM MN MO MP MQ MR MS MT MU MV MW MX MY MZ NA NC NE NF NG NI NL NO NP NR NU NZ OM PA PE PF PG PH PK PL PM PN PR PS PT PW PY QA RE RO RS RU RW SA SB SC SD SE SG SH SI SJ SK SL SM SN SO SR SS ST SV SX SY SZ TC TD TF TG TH TJ TK TL TM TN TO TR TT TV TW TZ UA UG UM US UY UZ VA VC VE VG VI VN VU WF WS YE YT ZA ZM ZW".split(" ");
const displayNames = new Intl.DisplayNames(["en"], { type: "region" });
export const WORLD_COUNTRIES = ISO_CODES
  .map(code => ({ code, name: displayNames.of(code) || code }))
  .filter(item => item.name !== item.code)
  .sort((a, b) => a.name.localeCompare(b.name));

const REGION_CODES: Record<string, string[]> = {
  "Asia": "AF AM AZ BD BH BN BT CN GE HK ID IL IN IQ IR IRN JO JP KG KH KP KR KW KZ LA LB LK MM MN MO MV MY NP OM PH PK PS QA SA SG SY TH TJ TL TM TR TW UZ VN YE".split(" "),
  "Africa": "AO BF BI BJ BW CD CF CG CI CM CV DJ DZ EG ER ET GA GH GM GN GQ GW KE KM LR LS LY MA MG ML MR MU MW MZ NA NE NG RW SC SD SL SN SO SS ST SZ TD TG TN TZ UG ZA ZM ZW".split(" "),
  "Europe": "AD AL AT AX BA BE BG BY CH CY CZ DE DK EE ES FI FO FR GB GG GI GR HR HU IE IM IS IT JE LI LT LU LV MC MD ME MK MT NL NO PL PT RO RS RU SE SI SJ SK SM UA VA".split(" "),
  "North America": "AG AI AW BB BL BM BQ BS BZ CA CR CU CW DM DO GD GL GP GT HN HT JM KN KY LC MF MQ MS MX NI PA PM PR SV SX TC TT US VC VG VI".split(" "),
  "South America": "AR BO BR CL CO EC FK GF GY PE PY SR UY VE".split(" "),
  "Oceania": "AS AU CC CK CX FJ FM GU HM KI MH MP NC NF NR NU NZ PF PG PN PW SB TK TL TO TV UM VU WF WS".split(" "),
  "Antarctica": ["AQ"]
};
export function regionFromCountryCode(code?: string): string {
  if (!code) return "Global";
  const normalized = code.toUpperCase();
  for (const [region, codes] of Object.entries(REGION_CODES)) if (codes.includes(normalized)) return region;
  return "Global";
}
export function countryFromCode(code?: string): string {
  if (!code) return "";
  return WORLD_COUNTRIES.find(item => item.code === code.toUpperCase())?.name || "";
}
